{"command":"python3 - << 'PY'
import math
obs=list(map(int,open('/tmp/dither_seq.txt').read().split()))
def genu(n,seed=0):
 x=seed; out=[]
 for i in range(n):
  x=(1664525*x+1013904223)&0xffffffff; out.append(x/4294967296.0)
 return out
v=genu(20000)
def r(vv): return math.floor(vv+0.5)
best=[]
for off in range(0,5000):
 for mode in range(4):
  vals=[]
  for i in range(100):
   a=v[off+2*i]; b=v[off+2*i+1]
   d=[a-b,a+b-1,b-a,1-a-b][mode]
   vals.append(r(d))
  mism=sum(a!=b for a,b in zip(vals,obs))
  if mism<30: best.append((mism,off,mode,vals[:20]))
print(sorted(best)[:10])
# Also one random per sample with triangular via sequential subtract (u_i - u_{i-1}) (SoX dither code famously uses previous random: tpdf = rand - previous_rand to save calls)
best=[]
for off in range(0,5000):
 for mode in range(2):
  vals=[]
  prev=v[off]
  for i in range(100):
   cur=v[off+i+1]; d=cur-prev if mode==0 else prev-cur; prev=cur; vals.append(r(d))
  mism=sum(a!=b for a,b in zip(vals,obs))
  if mism<30: best.append((mism,off,mode))
print("sequential diff",sorted(best)[:10])
PY
"}

