import subprocess, math
obs=list(map(int,open('/tmp/dither_seq.txt').read().split()))
def get(seed):
 out=subprocess.check_output(["/tmp/randseq",str(seed)],text=True)
 return [int(x)/2147483648.0 for x in out.split()]  # RAND_MAX+1 in glibc 2^31
def r(v): return math.floor(v+0.5)
for seed in [0,1,2,42,12345,1234,999,2147483647]:
 v=get(seed)
 for off in range(0,200):
  for mode,fn in enumerate([lambda a,b:a-b, lambda a,b:a+b-1]):
   vals=[r(fn(v[off+2*i],v[off+2*i+1])) for i in range(200)]
   mism=sum(a!=b for a,b in zip(vals,obs))
   if mism<50: print("pair",seed,off,mode,mism)
  # sequential diff one per
  vals=[]; prev=v[off]
  for i in range(200):
   cur=v[off+i+1]; vals.append(r(cur-prev)); prev=cur
  mism=sum(a!=b for a,b in zip(vals,obs))
  if mism<50: print("seqdiff",seed,off,mism)
print("done")
