vals=[]
for line in open('/tmp/dither_exact.txt'):
 p=line.split(); vals.append(float(p[3]))
print(vals[:5])
def score(u,mode=0):
    errs=[]
    for i,d in enumerate(vals):
        if mode==0: pred=u[2*i]-u[2*i+1]
        elif mode==1: pred=u[2*i]+u[2*i+1]-1
        elif mode==2: pred=u[2*i+1]-u[2*i]
        elif mode==3: pred=1-u[2*i]-u[2*i+1]
        errs.append(abs(pred-d))
    return sum(errs)/len(errs)
results=[]
def add(name,u):
    if len(u)<300: return
    for mode in range(4):
        for off in range(0,100):
            s=score(u[off:],mode)
            if s<0.35: results.append((s,name,mode,off))
# implementations
def mt(seed,n):
    # MT19937 init_genrand
    mt=[0]*624; mt[0]=seed & 0xffffffff
    for i in range(1,624): mt[i]=(1812433253*(mt[i-1] ^ (mt[i-1]>>30))+i) & 0xffffffff
    idx=624; out=[]
    def gen():
        nonlocal idx
        if idx>=624:
            for i in range(624):
                y=(mt[i]&0x80000000)|(mt[(i+1)%624]&0x7fffffff)
                mt[i]=mt[(i+397)%624] ^ (y>>1)
                if y&1: mt[i]^=0x9908b0df
            idx=0
        y=mt[idx]; idx+=1
        y^=y>>11; y^=(y<<7)&0x9d2c5680; y^=(y<<15)&0xefc60000; y^=y>>18
        return (y&0xffffffff)/4294967296.0
    return [gen() for _ in range(n)]
def xorshift(seed,n, shifts=(13,17,5)):
    x=seed & 0xffffffff or 1; out=[]
    a,b,c=shifts
    for i in range(n):
        x ^= (x<<a)&0xffffffff; x ^= x>>b; x ^= (x<<c)&0xffffffff; x&=0xffffffff; out.append(x/4294967296.0)
    return out
def lcg(mod,a,c,seed,n,extract=None):
    x=seed%mod; out=[]
    for i in range(n):
        x=(a*x+c)%mod; out.append(extract(x) if extract else x/mod)
    return out
def pcg(seed,seq=54,n=1000):
    state=0; inc=((seq<<1)|1) & ((1<<64)-1); out=[]
    def step():
        nonlocal state
        old=state; state=(old*6364136223846793005+inc) & ((1<<64)-1)
        x=((old>>18)^old)>>27; rot=old>>59
        return (((x>>rot)|(x<<((-rot)&31))) & 0xffffffff)/4294967296.0
    step(); state=(state+seed) & ((1<<64)-1); step()
    return [step() for _ in range(n)]
for seed in [0,1,42,12345,123456789,5489,0x12345678,999331,2147483647,0xe1b2c3d4 if False else 1234567]:
    add(f"mt{seed}", mt(seed,1000))
    add(f"xorshift{seed}", xorshift(seed,1000))
    add(f"pcg{seed}", pcg(seed,54,1000))
    add(f"pcgseq1 {seed}", pcg(seed,1,1000))
# LCG variants list
lcgs=[
 (2**32,1664525,1013904223),(2**32,1103515245,12345),(2**31,1103515245,12345),(2**32,214013,2531011),(2**32,69069,1),(2**32,69069,1234567),(2**32,22695477,1),(2**32,134775813,1),(2**32,1566083941,0),(2**32,1812433253,0),(2**31-1,16807,0),(2**31-1,48271,0),(2**31-1,69621,0),(2**32,2891336453,1),(2**32,747796405,2891336453),(2**32,277803737,1),(2**64,6364136223846793005,1442695040888963407),(2**64,2862933555777941757,3037000493),
]
for mod,a,c in lcgs:
