def read_wav(spec,filename,data,ftype_used,fmtdef,file_size_disp):
    audio=Audio(); audio.file_type='wav'; audio.filename=filename; audio.file_size=file_size_disp
    if len(data)<12:
        raise cant_open(filename, 'premature EOF')
    riff=data[0:4]; wave=data[8:12]
    if riff==b'RIFX': endian='big'
    elif riff in (b'RIFF',b'RF64'): endian='little'
    else: raise cant_open(filename, 'not a WAV file')
    if wave!=b'WAVE':
        raise cant_open(filename, 'not a WAV file')
    fmt=None; data_bytes=None; fact_samples=None; comments=[]; loops=None
    pos=12; premature=False; data_size_declared=None
    subformat=None
    while pos+8 <= len(data):
        cid=data[pos:pos+4]; csize=struct.unpack_from('>I' if endian=='big' else '<I',data,pos+4)[0]
        pos+=8
        if util.VERBOSITY>=4:
            dbug_msg('wav', f"Found chunk '{cid.decode('latin1').replace(chr(0),' ')}', size {csize}")
        chunk=data[pos:pos+csize]
        if cid==b'fmt ':
            fmt=chunk
        elif cid==b'data':
            data_size_declared=csize
            if csize>len(data)-pos:
                premature=True
                data_bytes=data[pos:]
            else:
                data_bytes=data[pos:pos+csize]
            # Continue parsing following chunks only if csize fits; otherwise break.
            if premature: break
        elif cid==b'fact':
            if len(chunk)>=4: fact_samples=struct.unpack_from('>I' if endian=='big' else '<I',chunk,0)[0]
        elif cid==b'LIST':
            # INFO subchunks
            if len(chunk)>=4 and chunk[:4]==b'INFO':
                p=4
                while p+8<=len(chunk):
                    sid=chunk[p:p+4]; sz=struct.unpack_from('>I' if endian=='big' else '<I',chunk,p+4)[0]; p+=8
                    sdata=chunk[p:p+sz]
                    if sid in (b'ICMT',b'INAM',b'IART',b'ICOP',b'ISFT',b'IPRD',b'ISBJ'):
                        try:
                            txt=sdata.rstrip(b'\x00').decode('utf-8','replace')
                            if txt: comments.append(txt)
                        except Exception: pass
                    p+=sz+(sz&1)
        elif cid==b'cue ':
            pass
        # advance padded
        pos += csize + (csize & 1)
    if fmt is None:
        raise cant_open(filename, 'missing fmt chunk')
    if len(fmt)<16:
        raise cant_open(filename, 'premature EOF')
    ef='>' if endian=='big' else '<'
    tag,ch,rate,byterate,blockalign,bits = struct.unpack_from(ef+'HHIIHH',fmt,0)
    cb=0; samples_per_block=None; valid_bits=bits; coefficients=None
    if len(fmt)>=18:
        cb=struct.unpack_from(ef+'H',fmt,16)[0]
    if tag==0xfffe:
        info_msg('wav','EXTENSIBLE')
        if len(fmt)>=40:
            valid_bits=struct.unpack_from(ef+'H',fmt,18)[0] or bits
            # subformat GUID first 2 bytes are format tag in endian
            subformat=struct.unpack_from(ef+'H',fmt,24)[0]
            tag=subformat
    extra=fmt[18:18+cb] if cb else b''
    if tag==1:
        enc = U if bits==8 else S
        if bits==0:
            raise format_error(filename,'data encoding or sample size was not specified')
    elif tag==3: enc=F
    elif tag==6: enc=A; bits=8
    elif tag==7: enc=MU; bits=8
    elif tag==0x11: enc=IMA; bits=4
    elif tag==0x02: enc=MS; bits=4
    elif tag==0x31 or tag==0x32: # GSM
        raise SoxFail('formats', f"can't open input file `{filename}': SoX was not built with GSM support", code=2)
    else:
        raise SoxFail('wav', f"unsupported format 0x{tag:02x}", code=2) if False else cant_open(filename, f"unsupported format 0x{tag:02x}")
    if enc==IMA:
        if len(extra)>=2: samples_per_block=struct.unpack_from(ef+'H',extra,0)[0]
    if enc==MS:
        if len(extra)>=4:
            samples_per_block=struct.unpack_from(ef+'H',extra,0)[0]
            ncoef=struct.unpack_from(ef+'H',extra,2)[0]
            coefficients=[]
            off=4
            for i in range(ncoef):
                if off+4<=len(extra): coefficients.append(struct.unpack_from(ef+'hh',extra,off)); off+=4
    audio.rate=float(rate); audio.channels=int(ch); audio.bits=int(valid_bits if tag not in (0x11,0x02) else 4)
    audio.encoding=enc; audio.endian=endian; audio.precision=util.encoding_precision(enc,audio.bits)
    audio.comments=comments
    if data_bytes is None: data_bytes=b''
    clips=[0]
    # User overrides: rate/channels override silently for WAV; bits/encoding overriding sample size triggers reinterpretation similar to raw over data_bytes.
    user_bits = spec.bits; user_enc = spec.encoding
    # SoX wav handler: if user specifies bits/encoding that changes sample size, warning and reinterprets.
    # Effects observed are complex; implement a reasonable subset:
    override_size=False
    if user_bits is not None and user_bits != audio.bits: override_size=True
    if user_enc is not None:
        # encoding names that imply a specific size (law/adpcm/float requiring bits)
        if user_enc in (MU,A): override_size=True
        elif user_enc==F: 
            # If user didn't specify bits, reference fails bad format. If bits specified, reinterpret as float.
            if user_bits is None:
                audio.encoding=None; audio.bits=0
                # finalize will raise encoding error
                if spec.rate is not None: audio.rate=float(spec.rate)
                if spec.channels is not None: audio.channels=int(spec.channels)
                return finalize_input_audio(audio,spec,filename)
            override_size=True
    if override_size:
        warn_msg('wav','User options overriding size read in .wav header')
        enc2=user_enc if user_enc is not None else enc
        bits2=user_bits if user_bits is not None else audio.bits
        if enc2 in (MU,A): bits2=8
        if enc2==S and bits2==8 and tag==1:
            enc2=U
        audio.encoding=enc2; audio.bits=int(bits2 or 0); audio.precision=util.encoding_precision(enc2,audio.bits)
        if spec.rate is not None: audio.rate=float(spec.rate)
        if spec.channels is not None: audio.channels=int(spec.channels)
        if spec.endian is not None: audio.endian=resolve_endian(spec.endian,endian)
        audio.reverse_bits=spec.reverse_bits; audio.reverse_nibbles=spec.reverse_nibbles
        audio.samples=decode_pcm_data(data_bytes,enc2,int(bits2),audio.endian,spec.reverse_bits,spec.reverse_nibbles,clips)
        audio.input_clips=clips[0]
        if premature: audio.read_warnings.append(('wav','Premature EOF on .wav input file'))
        return finalize_input_audio(audio,spec,filename)
    # Normal decode
    if spec.rate is not None: audio.rate=float(spec.rate)
    if spec.channels is not None: audio.channels=int(spec.channels)
    if spec.endian is not None: audio.endian=resolve_endian(spec.endian,endian)
    audio.reverse_bits=spec.reverse_bits; audio.reverse_nibbles=spec.reverse_nibbles
    if enc in (S,U,F,MU,A):
        # Container bits vs valid bits: samples are stored in blockalign/channels bytes; if fmt bits differs from valid (e.g. 24 in 32) decode as bits then shift down? Simplify: if valid<bits, decode container bits value then arithmetic shift right by diff before int_to_sample via decode with bits and then sample>>diff? We'll handle simple equal case and a shift adjustment.
        if valid_bits and bits and valid_bits<bits:
            raw=decode_pcm_data(data_bytes,enc,int(bits),audio.endian,spec.reverse_bits,spec.reverse_nibbles,clips)
            audio.samples=[s >> (bits-valid_bits) if False else s for s in raw]  # SoX aligns to MSB for WAV extensible usually
            audio.bits=int(valid_bits)
        else:
            audio.samples=decode_pcm_data(data_bytes,enc,int(audio.bits),audio.endian,spec.reverse_bits,spec.reverse_nibbles,clips)
    elif enc==IMA:
        audio.samples=decode_wav_ima(data_bytes, audio.channels, blockalign, samples_per_block, fact_samples)
    elif enc==MS:
        audio.samples=decode_wav_ms(data_bytes, audio.channels, blockalign, samples_per_block, coefficients, fact_samples)
    audio.input_clips=clips[0]
    if premature or (data_size_declared is not None and data_size_declared>len(data_bytes) and not spec.ignore_length):
        # data_bytes length equals available if premature set above; also if chunk truncated
        if premature: audio.read_warnings.append(('wav','Premature EOF on .wav input file'))
    return finalize_input_audio(audio,spec,filename)

def decode_wav_ima(data, channels, blockalign, samples_per_block, fact_samples):
    if not blockalign: return []
    out=[]
    for off in range(0,len(data),blockalign):
        block=data[off:off+blockalign]
        states=[]
        heads=[]
        pos=0
        for ch in range(channels):
            if pos+4>len(block): break
            pred=struct.unpack_from('<h',block,pos)[0]; idx=block[pos+2]
            states.append(IMAState(pred,idx)); heads.append(pred); pos+=4
        frames=[heads]
        # Following nibbles: For mono, sequential samples. For stereo, interleaving in groups of 8 samples per channel in each 4-byte unit? Standard IMA WAV stereo: data grouped.
        if channels==1:
            nib=[]
            for b in block[pos:]: nib.extend([b&15,(b>>4)&15])
            decoded=[states[0].decode_nibble(n) for n in nib]
            seq=heads+decoded
            out.extend(s<<16 for s in seq)
        else:
            # bytes after headers consist of groups: 4 bytes ch0 nibbles (8 samples), 4 bytes ch1, etc.
            seq=heads[:]
            per=[ [heads[ch]] for ch in range(channels)]
            p=pos
            chcycle=0
            while p < len(block):
                for ch in range(channels):
                    grp=block[p:p+4]; p+=4
                    for b in grp:
                        per[ch].append(states[ch].decode_nibble(b&15))
                        per[ch].append(states[ch].decode_nibble((b>>4)&15))
            maxf=max((len(x) for x in per),default=0)
            for i in range(maxf):
                for ch in range(channels):
                    if i<len(per[ch]): out.append(per[ch][i]<<16)
    if fact_samples is not None:
        out=out[:fact_samples*channels]
    return out

MS_COEF=[(256,0),(512,-256),(0,0),(192,64),(240,0),(460,-208),(392,-232)]
MS_ADAPTATION=[230,230,230,230,307,409,512,614,768,614,512,409,307,230,230,230]
def decode_wav_ms(data, channels, blockalign, samples_per_block, coefficients, fact_samples):
    if not blockalign: return []
    coefs=coefficients or MS_COEF
    out=[]
    # Per block headers per channel: predictor byte, delta i16, sample1 i16, sample2 i16.
    # Output begins sample2, sample1 then nibble-decoded samples.
    for off in range(0,len(data),blockalign):
        block=data[off:off+blockalign]
        pos=0; states=[]
        for ch in range(channels):
            if pos+7>len(block): break
            pred_idx=block[pos]; delta=struct.unpack_from('<h',block,pos+1)[0]
            s1=struct.unpack_from('<h',block,pos+3)[0]; s2=struct.unpack_from('<h',block,pos+5)[0]
            coef=coefs[pred_idx] if pred_idx < len(coefs) else (256,0)
            states.append({'delta':delta,'s1':s1,'s2':s2,'coef':coef})
            pos+=7
        per=[[st['s2'],st['s1']] for st in states]
        nib=[]
        for b in block[pos:]: nib.extend([(b>>4)&15,b&15])
        # Nibbles interleave channels sample by sample
        for i,n in enumerate(nib):
            if not states: break
            ch=i%channels if channels else 0
            st=states[ch]
            # MS ADPCM decode
            pred = (st['s1']*st['coef'][0] + st['s2']*st['coef'][1]) >> 8
            # Actually predictor uses sample1 as most recent? Formulas: pred = (s1*coef1 + s2*coef2)/256 where s1 is last sample, s2 second last. Our s1/s2 header order: sample1 is second output, sample2 first, so last=sample1, prev=sample2. coef tuple is (coef1,coef2) corresponding.
            sign = -1 if n&8 else 1
            delta_val = st['delta']
            # error = ((n&7)*2+1)*delta/8 ??? Standard: sample = pred + sign * (((n&7)<<3)+4)*delta>>3? Let's use common formulation:
            err = (( (n & 7) * 2 + 1) * delta_val) >> 3
            sample = pred + sign*err
            sample=max(-32768,min(32767,sample))
            # adapt delta
            st['delta'] = max(16, (MS_ADAPTATION[n]*delta_val)//256) if False else max(16, int(MS_ADAPTATION[n]*delta_val/256))
            st['s2']=st['s1']; st['s1']=sample
            per[ch].append(sample)
        maxf=max((len(x) for x in per),default=0)
        for i in range(maxf):
            for ch in range(channels):
                if ch < len(per) and i < len(per[ch]): out.append(per[ch][i]<<16)
    if fact_samples is not None:
        out=out[:fact_samples*channels]
    return out

