def resolve_endian(spec_endian, default='little'):
    if spec_endian is None: return default
    if spec_endian=='little': return 'little'
    if spec_endian=='big': return 'big'
    if spec_endian=='swap': return 'big' if default=='little' else 'little'
    return default

def apply_spec_to_signal(sig, spec, for_output=False):
    # Mutate sig fields based on user spec (only those in user_set handled by caller generally)
    if spec.rate is not None: sig.rate=float(spec.rate)
    if spec.channels is not None: sig.channels=int(spec.channels)
    if spec.bits is not None:
        sig.bits=int(spec.bits)
    if spec.encoding is not None:
        sig.encoding=spec.encoding
    # precision recompute in caller if needed
    if spec.endian is not None:
        sig.endian=resolve_endian(spec.endian, sig.endian or 'little')
    if 'reverse_bits' in spec.user_set or spec.reverse_bits: sig.reverse_bits=True
    if 'reverse_nibbles' in spec.user_set or spec.reverse_nibbles: sig.reverse_nibbles=True
    return sig

def format_error(name, detail, code=2):
    return SoxFail('formats', f"bad input format for file `{name}': {detail}", code=code)

def cant_open(name, reason, input_=True):
    kind='input' if input_ else 'output'
    # reasons from reference sometimes have trailing specifics; caller provides.
    return SoxFail('formats', f"can't open {kind} file `{name}': {reason}", code=2)

def finalize_input_audio(audio, spec, filename):
    # Common validation as in sox_open_read after startread.
    if audio.rate is None or audio.rate <= 0:
        raise format_error(filename, 'sample rate zero or negative')
    if audio.channels is None or audio.channels <= 0:
        raise format_error(filename, 'number of channels zero or negative')
    # encoding/bits check: null and text are special
    if audio.file_type not in ('null',):
        enc=audio.encoding
        if enc is None:
            raise format_error(filename, 'data encoding or sample size was not specified')
        if enc in (S,U,F) and not audio.bits:
            raise format_error(filename, 'data encoding or sample size was not specified')
    if audio.channels:
        # trim incomplete final frame
        n=len(audio.samples)//audio.channels*audio.channels
        if n != len(audio.samples): audio.samples=audio.samples[:n]
    return audio

