def float80_to_float(b):
    # 10-byte IEEE extended big-endian
    if len(b)<10: return 0.0
    sign=-1 if b[0]&0x80 else 1
    exp=((b[0]&0x7f)<<8)|b[1]
    mant=int.from_bytes(b[2:10],'big')
    if exp==0 and mant==0: return 0.0
    if exp==0x7fff: return float('inf')*sign
    # value = mant / 2^63 * 2^(exp-16383)
    return sign * (mant/9223372036854775808.0) * (2.0**(exp-16383))

def float_to_float80(x):
    if x==0: return b'\x00'*10
    sign=0
    if x<0: sign=1; x=-x
    # frexp: x = frac * 2^e where frac in [0.5,1), want mantissa in [1,2)
    frac,e=math.frexp(x)  # x = frac*2^e, frac in [0.5,1)
    exp=e-1+16383
    mant=int(round((frac*2) * (1<<63)))
    if mant >= (1<<64):
        mant >>=1; exp+=1
    out=bytearray()
    out.append((sign<<7)|((exp>>8)&0x7f)); out.append(exp&0xff); out+=mant.to_bytes(8,'big')
    return bytes(out)

