                try: channels=int(float(parts[-1]))
                except Exception: pass
            continue
        if s.startswith('%') or s.startswith('#'): continue
        parts=s.split()
        if len(parts)<2: continue
        vals=[]
        for p in parts[1:]:
            try: vals.append(float(p))
            except ValueError: pass
        if channels is None and vals: channels=len(vals)
        for v in vals[:channels]: samples.append(util.float_to_sample(v))
