# CVSD - approximate delta modulation (to refine)
class CVSDState:
    def __init__(self):
        self.value=0.0; self.step=0.005; self.last_bits=[]
    def decode_bit(self,bit):
        self.last_bits.append(bit); self.last_bits=self.last_bits[-3:]
        if len(self.last_bits)==3 and self.last_bits[0]==self.last_bits[1]==self.last_bits[2]:
            self.step=min(0.5,self.step*1.5+0.001)
        else:
            self.step=max(0.005,self.step*0.98)
        self.value += self.step if bit else -self.step
        self.value *= 0.999
        self.value=max(-1.0,min(1.0,self.value))
        return self.value
    def encode_sample(self,x):
        bit=1 if x>=self.value else 0
        self.decode_bit(bit)
        return bit

def cvsd_decode_data(data, reverse_bits=False):
    if reverse_bits: data=bytes(util._REVERSE_BITS[b] for b in data)
    st=CVSDState(); out=[]; clips=[0]
    for b in data:
        for i in range(7,-1,-1):
            out.append(util.double_to_sample(st.decode_bit((b>>i)&1),clips))
    return out

def cvsd_encode_data(samples, reverse_bits=False):
    st=CVSDState(); bits=[]
    for s in samples: bits.append(st.encode_sample(util.sample_to_double(s)))
    out=bytearray()
    for i in range(0,len(bits),8):
        b=0
        for j,bit in enumerate(bits[i:i+8]): b|=(bit<<(7-j))
        out.append(b)
    if reverse_bits: out=bytearray(util._REVERSE_BITS[b] for b in out)
    return bytes(out)

