def write_gsrt(audio,out_sig,opts):
    enc=out_sig.encoding if out_sig.encoding in (MU,A) else MU
    clips=[0]; data=encode_pcm_data(audio.samples,enc,8,'little',out_sig.reverse_bits,out_sig.reverse_nibbles,clips)
    header=bytearray(b'\x00'*512)
    total=512+len(data)
    struct.pack_into('>I',header,0,total//2)
    # date fields
    import time as _time
    if opts.get('repeatable'):
        year,mon,day,hour,minute=1970,1,1,0,0
    else:
        lt=_time.localtime(); year,mon,day,hour,minute=lt.tm_year,lt.tm_mon,lt.tm_mday,lt.tm_hour,lt.tm_min
    struct.pack_into('>I',header,8,year); header[12]=mon; header[13]=day; header[14]=hour; header[15]=minute
    header[16:24]=b'ring.bin'
    if enc==A:
        # observed difference at offset 40 area in a-law file: byte 0x08 at position 41? Place marker there (refine later)
        header[41]=8
    # checksum field at 4 left 0 for now
    return bytes(header)+data,clips[0]

