    elif code==0x06: rate=33333.3
    elif code==0xf6: rate=16666.7
    audio.rate=float(spec.rate if spec.rate is not None else rate); audio.channels=1; audio.encoding=S; audio.bits=12; audio.precision=12
    body=data[32:]
    # TXW sample bytes encode 12-bit samples in a non-linear 'squelched' format. Approximate by treating each byte as signed 8-bit companded: use table generated from observed sine later. For now map byte (signed?) to sample: values seem offset around??? Use signed byte <<20.
    audio.samples=[((b-256 if b>=128 else b) << 20) for b in body]
