def write_txw(audio,out_sig,opts):
    header=bytearray(b'\x00'*32); header[0:6]=b'LM8953'; header[20:24]=b'\x7f\x7f\x7f\x7f'
    # rate encoding bytes at 24..28 copied approximately from probes for 50000 vs 33333.
    if abs(out_sig.rate-50000)<10: header[24:32]=bytes.fromhex('c902b40110400000')
    elif abs(out_sig.rate-33333.3)<10: header[24:32]=bytes.fromhex('c9010e0106400052')
    else: header[24:32]=bytes.fromhex('c903e407f6400052')
