    header=bytearray(bytes.fromhex('370000106d0000107e000010cfac08551400000004520000103400000089000010250000007e0000102a')+b'record.app'+bytes.fromhex('0000000000000000'))
    # ensure 72 bytes: construct from probe pattern
    header=bytearray(b'\x00'*72)
    tmpl=bytes.fromhex('370000106d0000107e000010cfac08551400000004520000103400000089000010250000007e000010')
    header[:len(tmpl)]=tmpl; header[len(tmpl):len(tmpl)+10]=b'record.app'
