def detect_format_by_magic(data):
    if len(data)>=12 and data[:4] in (b'RIFF',b'RIFX') and data[8:12]==b'WAVE': return 'wav'
    if len(data)>=12 and data[:4]==b'FORM':
        t=data[8:12]
        if t==b'AIFF': return 'aiff'
        if t==b'AIFC': return 'aifc'
        if t==b'8SVX': return '8svx'
        if t==b'MAUD': return 'maud'
    if data[:4] in (b'.snd',b'dns.'): return 'au'
    if data[:4] in (b'.SoX',b'XoS.'): return 'sox'
    if data[:4]==b'2BIT': return 'avr'
    if data.startswith(b'NIST_1A'): return 'sph'
    if data.startswith(b'Creative Voice File\x1a'): return 'voc'
    if data.startswith(b'SOUND SAMPLE DATA '): return 'smp'
    if data.startswith(b'ALawSoundFile**'): return 'wve'
    if data.startswith(b'SOUND\x1a'): return 'sndt'
    if data.startswith(b'LM8953'): return 'txw'
    if len(data)>=4 and data[:2]==b'\x64\xa3': return 'sf'
    # GSRT has fixed filename ring.bin at 16 and 512 header; detection may be validated by handler's checksum/start.
    if len(data)>=512 and data[16:24]==b'ring.bin': return 'gsrt'
    # HCOM MacBinary: has FSSD type? A generated hcom file when renamed to noext: soxi -t printed hcom but exit1 - detection maybe by MacBinary validity / HCOM trailer. Skip.
    # PRC: EPOC UIDs are in many EPOC files; only detect if record.app present in header.
    if b'record.app' in data[:80]: return 'prc'
    return None

def extension_of(filename):
    base=os.path.basename(filename)
    if '.' not in base: return None
    # For filenames like 'file.' extension is empty string.
    return base.rsplit('.',1)[1].lower()

def open_input(spec, data, source_kind='file'):
    filename=spec.filename if spec.filename is not None else ''
    display_name=filename
    # file size for display
    if source_kind=='file': file_size_disp=len(data)
    elif source_kind=='stdin': file_size_disp=0
    else: file_size_disp=0 if source_kind in ('pipe','url') else len(data)
    if spec.special=='null': return read_null(spec,display_name,data,'null',FORMATS['null'],None)
    ftype_used=None; detected=False
    if spec.filetype is not None:
        ftype_used=spec.filetype.lower()
        canon=canonical_format(ftype_used)
        if canon is None:
            raise SoxFail('formats', f"no handler for given file type `{spec.filetype}'", code=2)
    else:
        canon_magic=detect_format_by_magic(data)
        if canon_magic is not None:
            canon=canon_magic; ftype_used=canon_magic; detected=True
            # SoX prints detected only for some handlers? Dat/sf(?) It printed for au/wav/sox/voc. It prints in sox_open_read when a handler succeeds via its read header function. For handlers with no 'check' (dat/raw) no.
            if canon not in ('sf',):
                info_msg('formats', f"detected file format type `{canon}'")
            else:
                info_msg('formats', f"detected file format type `{canon}'")
        else:
            ext=extension_of(filename)
            if ext is None:
                if filename=='-':
                    raise SoxFail('formats', "can't determine type of  `-", code=2) if False else SoxFail('formats', "can't determine type of  `-", code=2)
                raise SoxFail('formats', f"can't determine type of file `{filename}'", code=2)
            canon=canonical_format(ext)
            ftype_used=ext
            if canon is None:
                raise SoxFail('formats', f"no handler for file extension `{ext}'", code=2)
    fmtdef=FORMATS[canon]
    # SoX format identifiers for display: audio.file_type canonical, but side info: type used alias for raw defaults
    handler=fmtdef.handler
    reader=READERS.get(handler)
    if reader is None:
        raise SoxFail('formats', f"no handler for given file type `{ftype_used}'", code=2)
    audio=reader(spec,display_name,data,ftype_used,fmtdef,file_size_disp)
    # Store how type was determined for display (extension comparison)
    audio._type_used=ftype_used if hasattr(audio,'_type_used') else None
    # Attach dynamic attribute via object __dict__ impossible with slots; encode by using filename suffix logic in main display using spec.
    return audio

