def deinterleave(samples,ch):
    return [samples[c::ch] for c in range(ch)]
def interleave(chans):
    if not chans: return []
    out=[]; maxlen=max(len(c) for c in chans)
    for i in range(maxlen):
        for c in chans: out.append(c[i] if i<len(c) else 0)
    return out

def apply_volume_factor(audio,factor,mode='round'):
    clips=[0]; out=[]
    if mode=='trunc':
        for s in audio.samples: out.append(util.clip_sample_trunc(s*factor,clips))
    else:
        for s in audio.samples: out.append(util.clip_sample_round(s*factor,clips))
    audio.samples=out
    return clips[0]

def samples_peak(samples):
    m=0
    for s in samples:
        a=abs(s)
        if a>m: m=a
    return m

def samples_rms_per_channel(audio):
    chans=deinterleave(audio.samples,audio.channels) if audio.channels else []
    out=[]
    for chs in chans:
        if not chs: out.append(0.0)
        else: out.append(math.sqrt(sum((s/2147483648.0)**2 for s in chs)/len(chs)))
    return out

# Biquad coefficient generation (RBJ cookbook, normalized a0=1)
def biquad_coefs(kind, rate, freq, width_val=None, width_type='q', gain_db=0.0, constant_skirt=False):
    w=2*math.pi*freq/rate if rate else 0
    cw=math.cos(w); sw=math.sin(w)
    A=10**(gain_db/40.0)  # sqrt linear gain
    # alpha from width
    if width_type=='s':
        S=width_val if width_val is not None else 0.5
        alpha=sw/2*math.sqrt((A+1/A)*(1/S-1)+2) if S!=0 else sw/2
    elif width_type=='q':
        Q=width_val if width_val else 0.7071067811865475
        alpha=sw/(2*Q)
    elif width_type=='o':
        BW=width_val if width_val else 1.0
        # RBJ bandwidth in octaves
        alpha=sw*math.sinh(math.log(2)/2 * BW * w/sw) if sw!=0 else 0
    elif width_type in ('h','k'):
        bw=width_val if width_val else freq
        Q=freq/bw if bw else 0.7071
        alpha=sw/(2*Q)
    else:
        Q=width_val or 0.7071; alpha=sw/(2*Q)
    if kind=='lowpass':
        b=[(1-cw)/2,1-cw,(1-cw)/2]; a=[1+alpha,-2*cw,1-alpha]
    elif kind=='highpass':
        b=[(1+cw)/2,-(1+cw),(1+cw)/2]; a=[1+alpha,-2*cw,1-alpha]
    elif kind=='bandpass':
        if constant_skirt:
            b=[sw/2,0,-sw/2]
        else:
            b=[alpha,0,-alpha]
        a=[1+alpha,-2*cw,1-alpha]
    elif kind=='bandreject': # notch
        b=[1,-2*cw,1]; a=[1+alpha,-2*cw,1-alpha]
    elif kind=='allpass':
        b=[1-alpha,-2*cw,1+alpha]; a=[1+alpha,-2*cw,1-alpha]
    elif kind=='peaking':
        b=[1+alpha*A,-2*cw,1-alpha*A]; a=[1+alpha/A,-2*cw,1-alpha/A]
    elif kind=='lowshelf':
        sa=2*math.sqrt(A)*alpha
        b=[A*((A+1)-(A-1)*cw+sa),2*A*((A-1)-(A+1)*cw),A*((A+1)-(A-1)*cw-sa)]
        a=[(A+1)+(A-1)*cw+sa,-2*((A-1)+(A+1)*cw),(A+1)+(A-1)*cw-sa]
    elif kind=='highshelf':
        sa=2*math.sqrt(A)*alpha
        b=[A*((A+1)+(A-1)*cw+sa),-2*A*((A-1)+(A+1)*cw),A*((A+1)+(A-1)*cw-sa)]
        a=[(A+1)-(A-1)*cw+sa,2*((A-1)-(A+1)*cw),(A+1)-(A-1)*cw-sa]
    else:
        b=[1,0,0]; a=[1,0,0]
    a0=a[0]
    return [x/a0 for x in b],[x/a0 for x in a]

def apply_biquad(audio,b,a,clips):
    ch=audio.channels
    chans=deinterleave(audio.samples,ch)
    outch=[]
    for samples in chans:
        y=[]; x1=x2=y1=y2=0.0
        # SoX biquad does sample-by-sample double and converts with ROUND_CLIP (normalized by SAMPLE_MAX)
        for s in samples:
            x=s/float(util.SAMPLE_MAX)
            o=b[0]*x+b[1]*x1+b[2]*x2-a[1]*y1-a[2]*y2
            y.append(util.double_to_sample(o,clips))
            x2=x1; x1=x; y2=y1; y1=o
        outch.append(y)
    audio.samples=interleave(outch)

def apply_fir(audio,coefs,clips):
    ch=audio.channels; chans=deinterleave(audio.samples,ch); outch=[]
    for samples in chans:
        y=[]
        # convolution resulting in same length (SoX fir effect outputs input length? It may delay? We'll use causal and length same.)
        # Coefs are in order given; output at n sum coefs[i]*x[n - i + (len//2)?] SoX fir uses coefs as an FIR with first coef for most recent? We'll test against reference.
        L=len(coefs)
        for n in range(len(samples)):
            acc=0.0
            # Use samples as doubles
            for i,c in enumerate(coefs):
                idx=n-i
                if 0<=idx<len(samples): acc+=c*(samples[idx]/float(util.SAMPLE_MAX))
            y.append(util.double_to_sample(acc,clips))
        outch.append(y)
    audio.samples=interleave(outch)

