    parsed=ParsedCommand()
    pending=FileSpec()
    end_opts=False
    i=0
    def reset_pending():
        nonlocal pending
        pending=FileSpec()
    while i < len(args):
        tok=args[i]
        # Effect detection (only for non-option tokens or if end_opts)
        if end_opts or not tok.startswith('-') or tok=='-':
            if tok.lower() in effects.EFFECT_SET:
                parsed.effect_tokens=args[i:]; parsed.pending=pending.clone(); return parsed
            add_filename(parsed,pending,tok); reset_pending(); i+=1; continue
        if tok=='--':
            end_opts=True; i+=1; continue
        if tok.startswith('--'):
            raw=tok
            body=tok[2:]
            if '=' in body:
                given, eqval = body.split('=',1)
            else:
                given, eqval = body, None
            # Long resolution by given name
            if given in LONG_MAP:
                candidates=[given]
            else:
                candidates=[name for name,_,_ in LONG_OPTS if name.startswith(given)]
            if len(candidates)==0:
                warn_msg('getopt', f"parameter not recognized from `--{body}'")
                invalid_option_fail()
            if len(candidates)>1:
                # exact already handled
                warn_msg('getopt', f"parameter `--{body}' is ambiguous:")
