                    warn_msg('getopt', f"parameter `--{body}' could be `--{cand}'")
                invalid_option_fail()
            canon=candidates[0]; argkind,action=LONG_MAP[canon]
            val=None
            if argkind==1:
                if eqval is not None: val=eqval
                elif i+1 < len(args): val=args[i+1]; i+=1
                else:
                    warn_msg('getopt', f"`{canon}' requires an argument from `--{body}'")
                    invalid_option_fail()
            elif argkind==2:
                val=eqval  # may be None
            else:
                if eqval is not None:
                    # What does ref do for --help=x? It may treat as not recognized? We'll use getopt message approximate.
                    # Probe later; for now ignore the value for help/version etc if exact? Safer: warn not recognized from full token.
                    warn_msg('getopt', f"parameter not recognized from `--{body}'")
                    invalid_option_fail()
            i+=1
