            elif c=='h':
                print_main_usage(); early_exit(0)
            elif c=='D': gstate.no_dither=True
            elif c=='G': gstate.guard=True
            elif c=='R': gstate.repeatable=True; util.REPEATABLE=True
            elif c=='S': gstate.show_progress=True; gstate.show_progress_set=True
            elif c=='q': gstate.show_progress=False; gstate.show_progress_set=True
            elif c=='m': gstate.combine='mix'
            elif c=='M': gstate.combine='merge'
            elif c=='T': gstate.combine='multiply'
            elif c=='L': pending.endian='little'; pending.user_set.add('endian')
            elif c=='B': pending.endian='big'; pending.user_set.add('endian')
            elif c=='x': pending.endian='swap'; pending.user_set.add('endian')
            elif c=='N': pending.reverse_nibbles=True; pending.user_set.add('reverse_nibbles')
            elif c=='X': pending.reverse_bits=True; pending.user_set.add('reverse_bits')
