def audio_length_frames(audio):
    if audio is None: return 0
    if not getattr(audio,'length_known',True): return 0
    return audio.frames()

def display_name_and_type(spec, audio, is_output=False, out_canon=None):
    if spec is not None and spec.special=='null':
        return "'' (null)"
    name = spec.filename if spec is not None and spec.filename is not None else (audio.filename or '')
    canon = out_canon or (audio.file_type if audio is not None else None)
    # suffix if extension/type mismatch
    suffix=""
    if canon:
        fmtdef=FORMATS.get(canon)
        # aliases for this canon
        # Extension computed from full display name as reference (pipe command may end .wav)
        base=name
        ext=None
        if '.' in base:
            ext=base.rsplit('.',1)[1].lower()
            # If there are spaces, the extension would include them? Pipe commands: last token etc. Use ext only if no space/slash? Reference for pipe trimmed? It used filename string and perhaps strrchr, if command has args extension could include space/tool arguments. Avoid suffix decision complexities: if ext part contains space, then no match.
            if any(c in ext for c in ' \t/'):
                ext=None
        names_for_canon=[]
        if fmtdef:
            names_for_canon=[fmtdef.name.lower()]+[a.lower() for a in fmtdef.aliases]
        # Special: For raw cannons, names list include alias table reversed from ALL aliases mapping.
        names_for_canon=list(dict.fromkeys(names_for_canon+[a for a,c in formats.ALIAS.items() if c==canon]))
        if ext is None or ext not in names_for_canon:
            suffix=f" ({canon})"
        # Type forced via -t: reference display for -t f32 file.raw gave (f4) because ext raw not in f4 names. Works.
        # If spec.filetype explicitly and filename extension matches canon alias but user type alias differs (?) still no suffix in examples.
    return f"'{name}'{suffix}"

def make_info_text(kind, spec, audio_or_sig, comments, full=False, is_output=False, plan_length=None, out_canon=None):
    # audio_or_sig could be Audio (input) or Signal (output)
    if isinstance(audio_or_sig, util.Audio):
        audio=audio_or_sig; rate=audio.rate; ch=audio.channels; prec=audio.precision; enc=audio.encoding; bits=audio.bits; endian=audio.endian; rb=audio.reverse_bits; rn=audio.reverse_nibbles; length=audio_length_frames(audio); file_size=audio.file_size
    else:
        sig=audio_or_sig; audio=None; rate=sig.rate; ch=sig.channels; prec=sig.precision; enc=sig.encoding; bits=sig.bits; endian=sig.endian; rb=sig.reverse_bits; rn=sig.reverse_nibbles; length=plan_length or 0; file_size=None
    title='Input File' if kind=='input' else 'Output File'
    lines=[]
    lines.append("")
    lines.append(f"{title}     : {display_name_and_type(spec,audio,is_output,out_canon)}")
    lines.append(f"Channels       : {ch}")
    lines.append(f"Sample Rate    : {util.format_rate(rate)}")
    if prec:
        lines.append(f"Precision      : {prec}-bit")
    if length:
        duration=length/rate if rate else 0
        sectors=duration*75
        sect_str="%.6g" % sectors
        ineq='=' if abs(sectors-round(sectors))<1e-9 else '~'
        lines.append(f"Duration       : {util.format_time(duration)} = {int(length)} samples {ineq} {sect_str} CDDA sectors")
        if not is_output:
            lines.append(f"File Size      : {util.format_size(file_size or 0)}")
            bitrate=(file_size or 0)*8/duration if duration else 0
            lines.append(f"Bit Rate       : {util.format_size(bitrate)}")
    if enc:
        lines.append(f"Sample Encoding: {util.sample_encoding_full(bits,enc)}")
    if full:
        if enc and not (spec is not None and spec.special=='null'):
            lines.append(f"Endian Type    : {endian or 'little'}")
            lines.append(f"Reverse Nibbles: {'yes' if rn else 'no'}")
            lines.append(f"Reverse Bits   : {'yes' if rb else 'no'}")
    if comments:
        # comments is list of strings
        if len(comments)==1 and '\n' not in comments[0]:
            lines.append(f"Comment        : '{comments[0]}'")
        else:
            lines.append("Comments       : ")
            for c in comments:
                # each comment may contain newlines; print as-is line by line
                lines.extend(c.split('\n'))
    lines.append("")
    return "\n".join(lines)+"\n"

def soxi_one_value(audio, field):
    if field=='t': return audio.file_type or ''
    if field=='r': return util.format_rate(audio.rate)
    if field=='c': return str(audio.channels)
    if field=='s': return str(audio_length_frames(audio))
    if field=='d':
        length=audio_length_frames(audio); return util.format_time(length/audio.rate if audio.rate and length else 0)
    if field=='D':
        length=audio_length_frames(audio); return "%.6f" % (length/audio.rate if audio.rate and length else 0.0)
    if field=='b': return str(audio.bits or 0)
    if field=='B':
        length=audio_length_frames(audio)
        if not length or not audio.rate: return "0"
        return util.format_size((audio.file_size or 0)*8/(length/audio.rate))
    if field=='p': return str(audio.precision or 0)
    if field=='e': return util.encoding_soxi_name(audio.encoding) if audio.encoding else ''
    if field=='a':
        return '\n'.join(audio.comments) if audio.comments else ''
    return ''

def run_soxi(args):
    # args are soxi args (after removing --info if present)
    if len(args)==0:
        print_soxi_usage(); return 0
    field=None; total=False; files=[]
    i=0
    # Parse options only before first file. Support '--' separator.
    end_opts=False
    while i < len(args):
        tok=args[i]
        if end_opts or not tok.startswith('-') or tok=='-':
            files.extend(args[i:]); break
        if tok=='--':
            end_opts=True; i+=1; continue
        # Short options only; long --x gives first char '-' as option char in reference (WARN option '-' not recognized)
        chars=tok[1:]
        j=0
        bad=None
        while j < len(chars):
            c=chars[j]
            if c=='V':
                rest=chars[j+1:]
                if rest=='': util.VERBOSITY+=1
                else: set_verbosity_value(rest)
                j=len(chars); break
            elif c=='T': total=True
            elif c in 'trcsdDbBpea': field=c
            else:
                bad=c; break
            j+=1
        if bad is not None:
            print_soxi_usage()
            warn_msg('getopt', f"option `{bad}' not recognized")
            return 1
        i+=1
    exit_code=0
    audios=[]
    for fname in files:
        spec=FileSpec(fname)
        # soxi reads from file only; no stdin? '-' treated filename and fails determine type in open_input if data would be read - but reference fails without reading stdin? It said can't determine type of '-'. Our code below: if '-', fake data empty and let open_input fail with that msg.
        if fname=='-':
            # do not read stdin
            err=SoxFail('formats', "can't determine type of  `-'", code=2)
            fail_msg(err.module, err.text); exit_code=1; continue
        try:
            data=read_input_data(spec)
        except SoxFail as e:
            fail_msg(e.module,e.text); exit_code=1; continue
        except EarlyExit as e:
            return e.code
        # data tuple (bytes,source)
        data_bytes,source=data
        try:
            audio=formats.open_input(spec,data_bytes,source)
        except SoxFail as e:
            fail_msg(e.module,e.text); exit_code=1; continue
        audios.append(audio)
        if field is None:
            sys.stdout.write(make_info_text('input',spec,audio,audio.comments,full=False))
        elif not total:
            if field=='a':
                if audio.comments: sys.stdout.write('\n'.join(audio.comments)+"\n")
            else:
                sys.stdout.write(soxi_one_value(audio,field)+"\n")
    if total:
        if field in ('s','d','D',None):
            if field=='s':
                total_samples=sum(audio_length_frames(a) for a in audios)
                sys.stdout.write("%.6f\n" % float(total_samples))
            elif field=='d':
                total_dur=sum((audio_length_frames(a)/a.rate if a.rate else 0) for a in audios)
                sys.stdout.write(util.format_time(total_dur)+"\n")
            elif field=='D':
                total_dur=sum((audio_length_frames(a)/a.rate if a.rate else 0) for a in audios)
                sys.stdout.write("%.6f\n" % total_dur)
            elif field is None:
                # Full mode with -T: same as multiple files total below.
                if len(audios)>1:
                    total_dur=sum((audio_length_frames(a)/a.rate if a.rate else 0) for a in audios)
                    sys.stdout.write(f"Total Duration of {len(audios)} files: {util.format_time(total_dur)}\n")
        else:
            # warning to stderr without newline, literal soxi:
            sys.stderr.write("soxi: ignoring -T; n/a with other given option")
            # But values already printed? In reference, -T with other option prints per-file values in loop. Our loop above suppressed printing if total for s/d only; for others we entered not-total branch only if not total. Fix: if total and field not in s/d/D, values need printed. We printed none above.
            # Workaround: print them now (order stdout same)
            # However notice in loop, `elif not total` prevents printing; so print now.
            for audio in audios:
                if field=='a':
                    if audio.comments: sys.stdout.write('\n'.join(audio.comments)+"\n")
                else:
                    sys.stdout.write(soxi_one_value(audio,field)+"\n")
    else:
        if field is None and len(audios)>1:
            total_dur=sum((audio_length_frames(a)/a.rate if a.rate else 0) for a in audios)
            sys.stdout.write(f"Total Duration of {len(audios)} files: {util.format_time(total_dur)}\n")
    return exit_code

def read_input_data(spec):
    fname=spec.filename
