def expand_playlist(spec):
    # Returns list of specs if filename is a playlist (by extension), else [spec]
    fname=spec.filename or ''
    ext=formats.extension_of(fname) if fname else None
    if spec.filetype and spec.filetype.lower() in ('m3u','pls'): ext=spec.filetype.lower()
    if ext not in ('m3u','pls'): return [spec]
    if spec.special: return [spec]
    # Read playlist file. Errors handled like input open.
    try:
        data_bytes,source=read_input_data(spec)
    except SoxFail:
        raise
    text=data_bytes.decode('utf-8','ignore')
    entries=[]
    base=os.path.dirname(fname)
    if ext=='m3u':
        for line in text.splitlines():
            s=line.strip()
            if not s or s.startswith('#'): continue
            entries.append(s)
    else: # pls
        numbered={}
        for line in text.splitlines():
            m=re.match(r'File(\d+)\s*=\s*(.+)',line.strip(),re.I)
            if m: numbered[int(m.group(1))]=m.group(2).strip()
        entries=[numbered[k] for k in sorted(numbered)]
    out=[]
    for e in entries:
        s=spec.clone(); s.filetype=None; s.user_set.discard('type')
        if not os.path.isabs(e) and not e.startswith('|') and '://' not in e and base:
            s.filename=os.path.join(base,e)
        else: s.filename=e
        out.append(s)
    return out

def open_inputs(specs):
    audios=[]; eff_specs=[]
    for spec in specs:
        expanded=expand_playlist(spec)
        for s in expanded:
            eff_specs.append(s)
            if s.special=='null':
                audio=formats.open_input(s,b'','null')
            else:
                data_bytes,source=read_input_data(s)
                audio=formats.open_input(s,data_bytes,source)
            audios.append(audio)
    return audios,eff_specs

def combined_signal(audios,gstate):
    if not audios: return Signal()
    first=audios[0]
    sig=Signal(rate=first.rate,channels=first.channels,precision=first.precision,encoding=first.encoding,bits=first.bits,endian=first.endian,reverse_bits=first.reverse_bits,reverse_nibbles=first.reverse_nibbles)
    if gstate.combine in ('merge',):
        sig.channels=sum(a.channels for a in audios)
        sig.precision=max(a.precision for a in audios)
    elif gstate.combine in ('mix','mix-power','multiply'):
        sig.channels=max(a.channels for a in audios)
        sig.precision=max(a.precision for a in audios)
    elif gstate.combine=='sequence':
        pass
    # Length: concat sum, others max
    if all(a.length_known and not a.is_infinite for a in audios):
        if gstate.combine=='concatenate': sig.length=sum(a.frames() for a in audios)
        else: sig.length=max((a.frames() for a in audios),default=0)
