def verify_combinable(audios,gstate):
    if len(audios)<=1: return
    if gstate.combine!='sequence':
        rates=[a.rate for a in audios]
        if any(abs(r-rates[0])>1e-9 for r in rates):
            fail_msg('sox', "Input files must have the same sample-rate"); raise EarlyExit(1)
    if gstate.combine=='concatenate':
        chs=[a.channels for a in audios]
        if any(c!=chs[0] for c in chs):
            fail_msg('sox', "Input files must have the same # channels"); raise EarlyExit(1)
    elif gstate.combine in ('mix','mix-power','multiply'):
        chs=[a.channels for a in audios]
        if any(c!=chs[0] for c in chs): warn_msg('sox', "Input files don't have the same # channels")

def combine_audios(audios, specs, gstate):
    if not audios: return Audio(), []
    # Returns (audio, deferred_clip_events) deferred events list of tuples to emit after effects/output according to ordering: [('balancing',name,count),('mix',count)]
    deferred=[]
    # Apply input volumes and auto balancing first per input, collecting clips.
    # Determine factors:
    n=len(audios)
    factors=[]
    any_manual=any(s.volume is not None for s in specs)
    for a,s in zip(audios,specs):
        if s.volume is not None: factors.append(s.volume)
        else:
            if n>1 and not any_manual and gstate.combine=='mix': factors.append(1.0/n)
            elif n>1 and not any_manual and gstate.combine=='mix-power': factors.append(1.0/math.sqrt(n))
            else: factors.append(1.0)
    processed=[]
    for a,s,f in zip(audios,specs,factors):
        b=a.clone()
        if f!=1.0:
            clips=[0]
            b.samples=[util.clip_sample_round(x*f,clips) for x in b.samples]
            # round_away via clip_sample_round uses round_away
            if clips[0]: deferred.append(('balancing',s.filename,clips[0]))
            # volume increases precision approx
            if f not in (0,1):
                b.precision=min(32,b.precision + max(0,int(-math.log2(abs(f))))+1) if abs(f)<1 else b.precision
        processed.append(b)
    if gstate.combine in ('concatenate','sequence'):
        # Sequence here will be handled separately in caller; for concatenate join.
        first=processed[0].clone()
        samples=[]
        for a in processed: samples.extend(a.samples)
        first.samples=samples
        first.is_infinite=any(a.is_infinite for a in processed)
        first.length_known=all(a.length_known for a in processed)
        # Keep input comments from first only (already in first)
        first.read_warnings=[]
        for a in processed: first.read_warnings.extend(a.read_warnings)
        return first,deferred
    if gstate.combine=='merge':
        ch=sum(a.channels for a in processed); frames=max((a.frames() for a in processed),default=0)
        out=processed[0].clone(); out.channels=ch; out.samples=[0]*(frames*ch); out.precision=max(a.precision for a in processed)
        for idx,a in enumerate(processed):
            base=sum(p.channels for p in processed[:idx])
            for fr in range(a.frames()):
                for c in range(a.channels):
                    out.samples[fr*ch+base+c]=a.samples[fr*a.channels+c]
        out.read_warnings=[]; 
        for a in processed: out.read_warnings.extend(a.read_warnings)
        return out,deferred
    if gstate.combine in ('mix','mix-power','multiply'):
        ch=max(a.channels for a in processed); frames=max((a.frames() for a in processed),default=0)
        out=processed[0].clone(); out.channels=ch; out.precision=max(a.precision for a in processed)
        samples=[]; mixclips=[0]
        for fr in range(frames):
            for c in range(ch):
                vals=[]
                for a in processed:
                    if c<a.channels and fr<a.frames(): vals.append(a.samples[fr*a.channels+c])
                    else: vals.append(0)
                if gstate.combine=='multiply':
                    # multiply normalized values
                    prod=1.0
                    for v in vals: prod*=v/2147483648.0
                    # result sample = prod * 2147483648 ? For multiple, product of normalized -> one normalization. Use double_to_sample-like with P?
                    # Observational: for two samples, output sample = (a * b) / 2147483648 ? (since normalized product * 2^31)
                    x=prod*2147483648.0
                    samples.append(util.clip_sample_round(x,mixclips))
                else:
                    ssum=sum(vals)
                    samples.append(util.clip_sample_round(ssum,mixclips) if False else (ssum if SAMPLE_MIN<=ssum<=SAMPLE_MAX else util.clip_sample_round(ssum,mixclips)))
        if mixclips[0]:
            deferred.insert(0,('mixcombining',None,mixclips[0]))
        out.samples=samples
        out.read_warnings=[]
        for a in processed: out.read_warnings.extend(a.read_warnings)
        # mixing increases precision
        out.precision=min(32,out.precision+1)
        return out,deferred
    return processed[0],deferred

def output_comments(outspec, audios):
    # Returns comments list for output based on spec / inputs / default
    comments=[]
    has_comment_opt=False
    if outspec.comment is not None:
        has_comment_opt=True
        if outspec.comment!='': comments=[outspec.comment]
    if outspec.comment_file is not None:
        has_comment_opt=True
        try:
            with open(outspec.comment_file,'r',encoding='latin1') as f: txt=f.read()
        except OSError:
            fail_msg('sox', f"Cannot open comment file `{outspec.comment_file}'"); raise EarlyExit(1)
        txt=txt.rstrip('\n').rstrip('\r')
        # Reference removes trailing newline only (one?) - file "one\ntwo\n" gave text "one\ntwo". If multiple trailing newlines, likely while last char newline remove all.
        txt=txt.rstrip('\n')
        if txt!='': comments=[txt]
    if not has_comment_opt:
        if audios and audios[0].comments: comments=list(audios[0].comments)
    if outspec.add_comments:
        comments.extend(outspec.add_comments)
    if not comments:
        comments=['Processed by SoX']
    return comments

def check_output_clobber(outspec,gstate):
    # Return True if permitted/exists handling. Raises SoxFail formats permission denied etc if no-clobber and not terminal/denied.
    fname=outspec.filename
    if fname in ('-','') or outspec.special in ('null','pipe'): return False
    exists=os.path.exists(fname)
    if exists and not gstate.clobber:
        warn_msg('sox', f"Output file `{fname}' already exists")
        # prompt if stdin is a tty
        permitted=False
        if sys.stdin.isatty():
            sys.stderr.write(f"{util.PROG} sox: overwrite `{fname}' (y/n)? ")
            sys.stderr.flush()
            try:
                ans=sys.stdin.readline()
            except Exception: ans=''
            permitted=ans.strip().lower().startswith('y')
        if not permitted:
            raise SoxFail('formats', f"permission to overwrite `{fname}' denied", code=2)
    return exists

