def output_comments(outspec, audios):
    # Returns comments list for output based on spec / inputs / default
    comments=[]
    has_comment_opt=False
    if outspec.comment is not None:
        has_comment_opt=True
        if outspec.comment!='': comments=[outspec.comment]
    if outspec.comment_file is not None:
        has_comment_opt=True
        try:
            with open(outspec.comment_file,'r',encoding='latin1') as f: txt=f.read()
        except OSError:
            fail_msg('sox', f"Cannot open comment file `{outspec.comment_file}'"); raise EarlyExit(1)
        txt=txt.rstrip('\n').rstrip('\r')
        # Reference removes trailing newline only (one?) - file "one\ntwo\n" gave text "one\ntwo". If multiple trailing newlines, likely while last char newline remove all.
        txt=txt.rstrip('\n')
        if txt!='': comments=[txt]
    if not has_comment_opt:
        if audios and audios[0].comments: comments=list(audios[0].comments)
    if outspec.add_comments:
        comments.extend(outspec.add_comments)
    if not comments:
        comments=['Processed by SoX']
    return comments

def check_output_clobber(outspec,gstate):
    # Return True if permitted/exists handling. Raises SoxFail formats permission denied etc if no-clobber and not terminal/denied.
    fname=outspec.filename
    if fname in ('-','') or outspec.special in ('null','pipe'): return False
    exists=os.path.exists(fname)
    if exists and not gstate.clobber:
        warn_msg('sox', f"Output file `{fname}' already exists")
        # prompt if stdin is a tty
        permitted=False
        if sys.stdin.isatty():
            sys.stderr.write(f"{util.PROG} sox: overwrite `{fname}' (y/n)? ")
            sys.stderr.flush()
            try:
                ans=sys.stdin.readline()
            except Exception: ans=''
            permitted=ans.strip().lower().startswith('y')
        if not permitted:
            raise SoxFail('formats', f"permission to overwrite `{fname}' denied", code=2)
    return exists

