def parse_synth_freq_token(tok, just_key=None):
    # Returns (f1, f2, sweep_char) in Hz, or None if invalid/unparseable.
    # Frequencies can have '%' semitone prefix for each, scientific note, or Hz with k suffix. Separator characters :, +, /, - between.
    # Ambiguity: note tokens can include '-' as separator? Sweep separator is one char; freq parts may themselves start % and negative semitone e.g. %-12. Scientific notes can have # etc.
    # Implement scanning for a separator that's not the sign after %.
    def one(s):
        if s is None or s=='': return None
        if s.startswith('%'):
            v=util.parse_number(s[1:])
            if v is None: return None
            return synth_semitone_to_freq(v, just_key)
        # scientific note: letter A-G, optional #/b, octave digit maybe negative?
        m=re.fullmatch(r'([A-Ga-g])([#b]?)(-?\d+)',s)
        if m:
            return synth_note_to_freq(m.group(1).upper()+m.group(2), int(m.group(3)), just_key)
        v=parse_freq(s)
        return v
    # Find separator: iterate chars, candidates at position >0.
    sep_idx=None; sep=None
    i=0
    while i < len(tok):
        c=tok[i]
        if c in ':+/':
            sep_idx=i; sep=c; break
        if c=='-' and i>0 and tok[i-1]!='%':
            # Avoid negative octave in a note? Notes are like C-1 as a single frequency (scientific pitch with octave -1). If token matches note pattern fully, don't treat minus as sep.
            if re.fullmatch(r'[A-Ga-g][#b]?-?\d+',tok): break
            sep_idx=i; sep=c; break
        i+=1
    if sep_idx is None:
        f=one(tok)
        if f is None: return None
        return (f,None,None)
    left=tok[:sep_idx]; right=tok[sep_idx+1:]
    if not left or not right: return None
    f1=one(left); f2=one(right)
    if f1 is None or f2 is None: return None
    return (f1,f2,sep)

def synth_semitone_to_freq(semi, just_key=None):
    # Equal temperament relative to A 440.
    if just_key is None:
        return 440.0 * (2**(semi/12.0))
    # Just intonation relative to key: semitone offset within scale from key. SoX -j key (integer semitones rel to A or a note) changes ratios for note names/% notation.
    # Approximate: compute degree in just scale relative to tonic frequency.
    # We'll implement via note ratios for major scale semitone offsets (just intonation 5-limit) for whole semitones in octave.
    key_semi=just_key
    tonic_freq=440.0 * (2**(key_semi/12.0))
    rel=semi-key_semi
