        if core and core[0] in '=+-': rel=core[0]; core=core[1:]
        pos=int(round(util.parse_time_position(core,rate)))
        if rel=='-': pos=total-pos
        excess=int(round(util.parse_time_position(parts[1],rate))) if len(parts)>1 else int(round(0.005*rate))
        leeway=int(round(util.parse_time_position(parts[2],rate))) if len(parts)>2 else int(round(0.005*rate))
        specs.append((pos,excess,leeway))
    # Process in reverse order to keep positions stable.
    samples=list(audio.samples)
    for pos,excess,leeway in sorted(specs,reverse=True):
