            if shape=='h': ga=math.cos(x*math.pi/2); gb=math.sin(x*math.pi/2); # constant gain half sine? For splice -h is half sine constant gain: factors maybe cos/sin but sum? 
            elif shape=='t': ga=1-x; gb=x
            elif shape=='q': ga=math.cos(x*math.pi/2); gb=math.sin(x*math.pi/2)
