            break
        chain_idx+=1
    return 0

def numbered_outspec(spec,n):
    s=spec.clone(); fname=s.filename or ''
    if '%n' in fname or re.search(r'%\d+n',fname):
        def repl(m):
            prefix=m.group(0)
            mm=re.match(r'%(\d*)n',prefix); width=int(mm.group(1)) if mm.group(1) else 0
            return str(n).zfill(width) if width else str(n)
        fname=re.sub(r'%\d*n',repl,fname)
    else:
        base,dot,ext=fname.rpartition('.')
        if dot and '/' not in ext:
            fname=f"{base}{n:02d}.{ext}"
        else:
            fname=f"{fname}{n:02d}"
    s.filename=fname; return s

def take_chain_segment(audio,chain):
    # Return (segment_audio, consumed_frames or None if all)
    total=audio.frames(); consumed=None
    for fx in chain:
        if fx.name=='trim' and fx.params.get('pos_samples'):
            pts=fx.params['pos_samples']
            if len(pts)>=2:
                consumed=max(pts)  # trim up to last position in this chain consumes up to its final stop position.
                # Actually pairs: a chain stops when trim reaches its last position; consumed is last position.
                consumed=pts[-1]
                break
        if fx.name=='synth' and fx.params.get('parsed',{}).get('length_samples'):
            consumed=fx.params['parsed']['length_samples']; break
    if consumed is None:
        return audio.clone(), None
    seg=audio.clone(); seg.samples=audio.samples[:consumed*audio.channels]; return seg,consumed

