vals=list(range(-32768,32768)); ref=open('/tmp/t/allref.ul','rb').read()
def make(qmode,negmode,bias,segmode,shiftmode):
 def enc(v):
  if qmode=='roundup': q=(v+2)//4 if v>=0 else -((-v+2)//4) if False else ((v<<16)+(1<<17))>>18
  elif qmode=='floor': q=v//4
  elif qmode=='trunc': q=int(v/4)
  elif qmode=='roundaway': q=(abs(v)+2)//4 * (1 if v>=0 else -1)
  if q<0: sign=0x80; mag=-q-1 if negmode=='minus1' else -q
  else: sign=0; mag=q
  biased=min(mag+bias, 8191+bias)
  if segmode=='bitlen6': exp=max(0,biased.bit_length()-6)
  elif segmode=='bitlen5': exp=max(0,biased.bit_length()-5)
  elif segmode=='ends':
   ends=[63,127,255,511,1023,2047,4095,8191]
   exp=next((i for i,e in enumerate(ends) if biased<=e),7)
  exp=min(7,exp)
  shift=exp+1 if shiftmode=='exp+1' else (exp if exp else 1)
  mant=(biased>>shift)&15
  return (~(sign|(exp<<4)|mant))&255
 return enc
